import base64,hashlib,json,runpy,zlib
from pathlib import Path
root=Path("/home/root/aura-calibration-contract-20261022/23a5c619b483e65c")
root.mkdir(parents=True,exist_ok=True,mode=0o700)
expected={'sface_calibration.py': '23a5c619b483e65c7dd152e5a225df55763ac2936dbf5ae717c6ec998fb19e5c', 'calibration_contract_check.py': '368cab5d9140b1e83bc1d399deb59290bbcf95a518dfc9f0190ee99c2c253bac'}
files=json.loads(zlib.decompress(base64.b64decode('')))
for name,value in files.items():
 raw=base64.b64decode(value);assert hashlib.sha256(raw).hexdigest()==expected[name]
 p=root/name
 if p.exists():assert p.read_bytes()==raw
 else:
  with p.open("xb") as out:out.write(raw)
ns=runpy.run_path(str(root/"calibration_contract_check.py"))
ns["main"](["--module",str(root/"sface_calibration.py"),"--expected-sha256",expected["sface_calibration.py"]])
